-- +goose Up
-- Phase 6: SSH keys generated by Alice and their private keys, rotation policies and rotation runs
-- (spec §7.2-§7.4, §13.4-§13.6; R41). Same conventions as 00006 and 00008: closed lists for values
-- Alice owns, format checks for names, no clock defaults.

-- Generated SSH keys keep their private key here (owner ssh_key, PKCS #8 DER for every type; R41 row 2).
-- Ed25519 is new. download_count and last_downloaded_at belong to the audited download. A retired key's
-- private key is destroyed 30 days after its retirement (R41 row 23): its envelope columns become NULL
-- once, with destroyed_at; nothing else may ever change an envelope (managed_private_keys_guard).
ALTER TABLE managed_private_keys DROP CONSTRAINT managed_private_keys_owner_type_check;
ALTER TABLE managed_private_keys ADD CONSTRAINT managed_private_keys_owner_type_check
    CHECK (owner_type IN ('certificate', 'csr', 'ssh_key'));
ALTER TABLE managed_private_keys DROP CONSTRAINT managed_private_keys_algorithm_check;
ALTER TABLE managed_private_keys ADD CONSTRAINT managed_private_keys_algorithm_check
    CHECK (algorithm IN ('rsa', 'ecdsa', 'ed25519'));
ALTER TABLE managed_private_keys DROP CONSTRAINT managed_private_keys_check;
ALTER TABLE managed_private_keys ADD CONSTRAINT managed_private_keys_bits_check CHECK ((algorithm = 'rsa' AND bits >= 2048)
    OR (algorithm = 'ecdsa' AND bits IN (256, 384)) OR (algorithm = 'ed25519' AND bits = 256));
ALTER TABLE managed_private_keys ADD CONSTRAINT managed_private_keys_ssh_types CHECK (owner_type <> 'ssh_key'
    OR (algorithm = 'ed25519') OR (algorithm = 'rsa' AND bits IN (3072, 4096)) OR (algorithm = 'ecdsa' AND bits = 256));
ALTER TABLE managed_private_keys ADD CONSTRAINT managed_private_keys_ed25519_is_ssh CHECK (algorithm <> 'ed25519' OR owner_type = 'ssh_key');
ALTER TABLE managed_private_keys ADD COLUMN download_count integer NOT NULL DEFAULT 0 CHECK (download_count >= 0);
ALTER TABLE managed_private_keys ADD COLUMN last_downloaded_at timestamptz;
ALTER TABLE managed_private_keys ADD COLUMN destroyed_at timestamptz;
ALTER TABLE managed_private_keys ALTER COLUMN ciphertext DROP NOT NULL, ALTER COLUMN nonce DROP NOT NULL,
    ALTER COLUMN wrapped_dek DROP NOT NULL, ALTER COLUMN key_version DROP NOT NULL;
ALTER TABLE managed_private_keys ADD CONSTRAINT managed_private_keys_destroyed CHECK (
    (destroyed_at IS NULL AND ciphertext IS NOT NULL AND nonce IS NOT NULL AND wrapped_dek IS NOT NULL AND key_version IS NOT NULL)
    OR (destroyed_at IS NOT NULL AND owner_type = 'ssh_key' AND ciphertext IS NULL AND nonce IS NULL AND wrapped_dek IS NULL
        AND key_version IS NULL));

-- +goose StatementBegin
CREATE FUNCTION managed_private_keys_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    IF OLD.destroyed_at IS NOT NULL THEN
        RAISE EXCEPTION 'a destroyed private key cannot change' USING ERRCODE = 'Z1009';
    END IF;
    IF NEW.id <> OLD.id OR NEW.owner_type <> OLD.owner_type OR NEW.algorithm <> OLD.algorithm OR NEW.bits <> OLD.bits
            OR NEW.public_key_sha256 <> OLD.public_key_sha256 OR NEW.created_at <> OLD.created_at
            OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
        RAISE EXCEPTION 'a private key''s identity cannot change' USING ERRCODE = 'Z1009';
    END IF;
    IF NEW.destroyed_at IS NOT NULL THEN
        -- Destruction: the envelope goes (the CHECK requires NULLs), the counters stay, and only the private
        -- key of a retired key goes (R41 row 23, ruling S5): a live key's envelope is never destroyed.
        IF NEW.download_count <> OLD.download_count OR NEW.last_downloaded_at IS DISTINCT FROM OLD.last_downloaded_at THEN
            RAISE EXCEPTION 'a destruction changes nothing but the envelope' USING ERRCODE = 'Z1009';
        END IF;
        -- The key row is read FOR SHARE: a concurrent un-retire (ssh_keys_guard reads this row FOR SHARE) and this
        -- destruction cannot both pass (ruling G13).
        IF NOT EXISTS (SELECT 1 FROM public.ssh_keys k WHERE k.private_key_id = NEW.id AND k.retired_at IS NOT NULL FOR SHARE OF k) THEN
            RAISE EXCEPTION 'only the private key of a retired key is destroyed' USING ERRCODE = 'Z1009';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.ciphertext IS DISTINCT FROM OLD.ciphertext OR NEW.nonce IS DISTINCT FROM OLD.nonce THEN
        RAISE EXCEPTION 'a private key''s payload cannot be replaced' USING ERRCODE = 'Z1009';
    END IF;
    -- The master-key re-wrap (SEC-041/042) changes the wrapped DEK and the key version together, upwards, and
    -- never the payload (ciphertext, nonce).
    IF NEW.wrapped_dek IS DISTINCT FROM OLD.wrapped_dek OR NEW.key_version IS DISTINCT FROM OLD.key_version THEN
        IF NEW.wrapped_dek IS NOT DISTINCT FROM OLD.wrapped_dek OR NEW.key_version IS NOT DISTINCT FROM OLD.key_version
                OR NEW.key_version < OLD.key_version THEN
            RAISE EXCEPTION 'a re-wrap changes the wrapped key and the key version together, upwards' USING ERRCODE = 'Z1009';
        END IF;
    END IF;
    IF NEW.download_count < OLD.download_count OR NEW.download_count > OLD.download_count + 1 THEN
        RAISE EXCEPTION 'a download counts one' USING ERRCODE = 'Z1009';
    END IF;
    -- The download time moves only with the count, forwards.
    IF NEW.last_downloaded_at IS DISTINCT FROM OLD.last_downloaded_at
            OR NEW.download_count = OLD.download_count + 1 THEN
        IF NEW.download_count <> OLD.download_count + 1 OR NEW.last_downloaded_at IS NULL
                OR (OLD.last_downloaded_at IS NOT NULL AND NEW.last_downloaded_at < OLD.last_downloaded_at) THEN
            RAISE EXCEPTION 'the download time changes only with the count, forwards' USING ERRCODE = 'Z1009';
        END IF;
    END IF;
    RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER managed_private_keys_guard BEFORE UPDATE ON managed_private_keys
    FOR EACH ROW EXECUTE FUNCTION managed_private_keys_guard();

-- A generated key (managed) has exactly one private key and is never the platform key (R41 rows 1-2).
-- rotated_from links a rotation's new key to the key it replaces; retired_at is set when no location
-- of a rotated key is live any more (R41 row 23).
ALTER TABLE ssh_keys ADD COLUMN private_key_id uuid UNIQUE REFERENCES managed_private_keys (id);
ALTER TABLE ssh_keys ADD COLUMN key_comment text NOT NULL DEFAULT '' CHECK (key_comment ~ '^[!-~]{0,100}$');
ALTER TABLE ssh_keys ADD COLUMN rotated_from uuid REFERENCES ssh_keys (id);
ALTER TABLE ssh_keys ADD COLUMN created_by uuid REFERENCES users (id);
ALTER TABLE ssh_keys ADD CONSTRAINT ssh_keys_managed_has_private_key CHECK (managed = (private_key_id IS NOT NULL));
ALTER TABLE ssh_keys ADD CONSTRAINT ssh_keys_managed_is_not_platform CHECK (NOT (managed AND is_platform_key));
ALTER TABLE ssh_keys ADD CONSTRAINT ssh_keys_label_length CHECK (char_length(label) <= 100);
CREATE INDEX ssh_keys_rotated_from ON ssh_keys (rotated_from) WHERE rotated_from IS NOT NULL;

-- A generated key's private key is an SSH-owned one that still exists; a retired key whose private key was
-- destroyed is not un-retired (ruling S5: the key is then gone for good).
-- +goose StatementBegin
CREATE FUNCTION ssh_keys_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.private_key_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.managed_private_keys p
                WHERE p.id = NEW.private_key_id AND p.owner_type = 'ssh_key' AND p.destroyed_at IS NULL) THEN
            RAISE EXCEPTION 'a generated key''s private key is a live SSH private key' USING ERRCODE = 'Z1014';
        END IF;
    ELSIF OLD.retired_at IS NOT NULL AND NEW.retired_at IS NULL AND NEW.private_key_id IS NOT NULL
            AND EXISTS (SELECT 1 FROM public.managed_private_keys p WHERE p.id = NEW.private_key_id AND p.destroyed_at IS NOT NULL FOR SHARE OF p) THEN
        RAISE EXCEPTION 'a key whose private key was destroyed is not un-retired' USING ERRCODE = 'Z1014';
    END IF;
    RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER ssh_keys_guard BEFORE INSERT OR UPDATE OF retired_at ON ssh_keys
    FOR EACH ROW EXECUTE FUNCTION ssh_keys_guard();

-- One policy per live key (§13.6 item 10). It follows the key: a completed rotation moves ssh_key_id
-- to the new key. enabled implies a next run (R41 row 12). preview_mailed_at bounds on-demand preview
-- emails (row 16).
CREATE TABLE rotation_policies (
    id                  uuid PRIMARY KEY,
    ssh_key_id          uuid NOT NULL REFERENCES ssh_keys (id),
    name                text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
    enabled             boolean NOT NULL DEFAULT false,
    interval_days       integer NOT NULL CHECK (interval_days BETWEEN 1 AND 3650),
    overlap_minutes     integer NOT NULL DEFAULT 10080 CHECK (overlap_minutes BETWEEN 0 AND 129600),
    notify_before_hours integer NOT NULL DEFAULT 24 CHECK (notify_before_hours BETWEEN 1 AND 168),
    new_key_type        text NOT NULL DEFAULT 'same' CHECK (new_key_type IN ('same', 'ed25519', 'rsa-3072', 'rsa-4096', 'ecdsa-p256')),
    next_run_at         timestamptz,
    preview_mailed_at   timestamptz,
    version             integer NOT NULL DEFAULT 1 CHECK (version >= 1),
    created_by          uuid REFERENCES users (id),
    created_at          timestamptz NOT NULL,
    updated_at          timestamptz NOT NULL,
    deleted_at          timestamptz,
    CHECK (deleted_at IS NOT NULL OR enabled = (next_run_at IS NOT NULL))
);
CREATE UNIQUE INDEX rotation_policies_one_per_key ON rotation_policies (ssh_key_id) WHERE deleted_at IS NULL;
CREATE INDEX rotation_policies_due ON rotation_policies (next_run_at) WHERE enabled AND deleted_at IS NULL;

-- A policy's key is a key Alice generated, not retired, and never Alice's own key (F-36, SEC-081): the
-- service refuses first; this holds even if it had a bug. Same search_path discipline as 00005.
-- +goose StatementBegin
CREATE FUNCTION rotation_policies_check_key() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
DECLARE
    platform_fp text;
BEGIN
    -- A deleted policy, and a policy switched off on its own key, are not checked (an off policy of a retired key
    -- must stay switchable); an insert, a move to another key and switching on are.
    IF NEW.deleted_at IS NOT NULL OR (TG_OP = 'UPDATE' AND NOT NEW.enabled AND NEW.ssh_key_id = OLD.ssh_key_id) THEN
        RETURN NEW;
    END IF;
    SELECT public_info->>'fingerprint' INTO platform_fp FROM public.credentials WHERE purpose = 'platform_ssh';
    IF NOT EXISTS (SELECT 1 FROM public.ssh_keys k WHERE k.id = NEW.ssh_key_id AND k.managed AND NOT k.is_platform_key
                   AND k.retired_at IS NULL AND k.fingerprint_sha256 IS DISTINCT FROM platform_fp) THEN
        RAISE EXCEPTION 'a rotation policy needs a live key Alice generated, never Alice''s own key' USING ERRCODE = 'Z1010';
    END IF;
    RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER rotation_policies_key_check BEFORE INSERT OR UPDATE OF ssh_key_id, deleted_at, enabled ON rotation_policies
    FOR EACH ROW EXECUTE FUNCTION rotation_policies_check_key();

-- One rotation run (§7.4; R41 rows 17-22). plan is the public preview (no secret: lines carry public keys
-- and options only); plan_digest is what a start must match. paused_license is the lock flag (L-83..L-86);
-- removal_allowed is set only on entering removing_old, which needs verified_at (old-key rule).
-- The database enforces the state machine (rotations_guard below): an insert is a preview, a finished run
-- never changes, the keys of a run are fixed, a status change follows the edges of C8.
CREATE TABLE rotations (
    id                   uuid PRIMARY KEY,
    policy_id            uuid NOT NULL REFERENCES rotation_policies (id),
    old_ssh_key_id       uuid NOT NULL REFERENCES ssh_keys (id),
    new_ssh_key_id       uuid REFERENCES ssh_keys (id),
    trigger              text NOT NULL CHECK (trigger IN ('scheduled', 'manual')),
    status               text NOT NULL CHECK (status IN ('dry_run_notified', 'adding_new', 'verifying_new', 'overlap',
                             'removing_old', 'completed', 'rolling_back', 'aborted', 'needs_attention', 'cancelled')),
    paused_license       boolean NOT NULL DEFAULT false,
    paused_at            timestamptz,
    awaiting_decision    boolean NOT NULL DEFAULT false,
    decision_due_at      timestamptz,
    plan                 jsonb NOT NULL CHECK (jsonb_typeof(plan) = 'object' AND octet_length(plan::text) <= 2097152),
    plan_digest          text NOT NULL CHECK (plan_digest ~ '^[0-9a-f]{64}$'),
    new_key_type         text NOT NULL CHECK (new_key_type IN ('ed25519', 'rsa-3072', 'rsa-4096', 'ecdsa-p256')),
    overlap_minutes      integer NOT NULL CHECK (overlap_minutes BETWEEN 0 AND 129600),
    planned_for          timestamptz NOT NULL,
    notified_at          timestamptz NOT NULL,
    started_at           timestamptz,
    verified_at          timestamptz,
    overlap_until        timestamptz,
    reminder_sent_at     timestamptz,
    removal_allowed      boolean NOT NULL DEFAULT false,
    kept_count           integer NOT NULL DEFAULT 0 CHECK (kept_count >= 0),   -- locations where the old key stays (S11)
    continued_by         uuid REFERENCES users (id),
    continued_at         timestamptz,
    renotified_at        timestamptz,
    finished_at          timestamptz,
    result_code          text NOT NULL DEFAULT '' CHECK (result_code = '' OR result_code ~ '^[a-z][a-z0-9_]{0,40}\.[a-z][a-z0-9_]{0,60}$'),
    created_by           uuid REFERENCES users (id),
    created_at           timestamptz NOT NULL,
    updated_at           timestamptz NOT NULL,
    version              integer NOT NULL DEFAULT 1 CHECK (version >= 1),
    CONSTRAINT rotations_removing_needs_allowed CHECK (status <> 'removing_old' OR removal_allowed),
    CONSTRAINT rotations_allowed_needs_verified CHECK (NOT removal_allowed OR (verified_at IS NOT NULL AND new_ssh_key_id IS NOT NULL)),
    CONSTRAINT rotations_new_differs CHECK (new_ssh_key_id IS DISTINCT FROM old_ssh_key_id),
    CONSTRAINT rotations_new_key_set CHECK (status IN ('dry_run_notified', 'cancelled') OR new_ssh_key_id IS NOT NULL),
    CONSTRAINT rotations_paused_pair CHECK (paused_license = (paused_at IS NOT NULL)),
    CONSTRAINT rotations_decision_pair CHECK (awaiting_decision = (decision_due_at IS NOT NULL)),
    CONSTRAINT rotations_finished_pair CHECK ((status IN ('completed', 'aborted', 'needs_attention', 'cancelled')) = (finished_at IS NOT NULL))
);
CREATE UNIQUE INDEX rotations_new_key_once ON rotations (new_ssh_key_id) WHERE new_ssh_key_id IS NOT NULL;
CREATE UNIQUE INDEX rotations_one_live_per_key ON rotations (old_ssh_key_id)
    WHERE status NOT IN ('completed', 'aborted', 'needs_attention', 'cancelled');
CREATE UNIQUE INDEX rotations_one_live_per_policy ON rotations (policy_id)
    WHERE status NOT IN ('completed', 'aborted', 'needs_attention', 'cancelled');
CREATE INDEX rotations_live ON rotations (status) WHERE status NOT IN ('completed', 'aborted', 'needs_attention', 'cancelled');

-- One location of the old key in a run (§13.6 items 3-6; R41 rows 19, 27, 29). The CHECKs and the trigger
-- below carry the old-key rule: nothing is "removing" or "removed" without a verified and freshly
-- re-verified new key, and the re-verification is at most 15 minutes before the removal was sent.
-- Freshness is relative to the application's own times by design: the application clock is injected (tests
-- and the harness jump it), so the database never reads now(); it refuses unrelated or stale-looking values
-- (the re-check is the column the removal relied on, it is not older than the verification, the removal
-- follows it by at most 15 minutes).
CREATE TABLE rotation_locations (
    id                uuid PRIMARY KEY,
    rotation_id       uuid NOT NULL REFERENCES rotations (id),
    n                 integer NOT NULL CHECK (n BETWEEN 1 AND 10000),
    old_location_id   uuid NOT NULL REFERENCES ssh_key_locations (id),
    target_id         uuid NOT NULL REFERENCES targets (id),
    os_user           text NOT NULL CHECK (char_length(os_user) BETWEEN 1 AND 64),
    file_path         text NOT NULL CHECK (char_length(file_path) BETWEEN 1 AND 4096),
    options           text NOT NULL DEFAULT '' CHECK (char_length(options) <= 4096),
    verify_note       text NOT NULL DEFAULT '' CHECK (verify_note IN ('', 'root_login_disabled', 'from_option', 'login_without_key')),
    state             text NOT NULL CHECK (state IN ('planned', 'skipped', 'cancelled', 'adding', 'added', 'add_failed', 'verified',
                          'unverifiable', 'verify_failed', 'kept_old', 'removing', 'removed', 'remove_failed', 'undoing', 'undone',
                          'undo_failed')),
    skip_reason       text NOT NULL DEFAULT '' CHECK (skip_reason = '' OR skip_reason ~ '^[a-z][a-z0-9_]{0,63}$'),
    error_code        text NOT NULL DEFAULT '' CHECK (error_code = '' OR error_code ~ '^[a-z][a-z0-9_]{0,40}\.[a-z][a-z0-9_]{0,60}$'),
    add_op_id         uuid,
    add_sent_at       timestamptz,                 -- the first add send; never moves (G16)
    add_resend_count  integer NOT NULL DEFAULT 0 CHECK (add_resend_count BETWEEN 0 AND 1000),   -- add re-sends (G25)
    add_resent_at     timestamptz,                 -- the latest add re-send (G25)
    added_line_no     integer CHECK (added_line_no IS NULL OR added_line_no >= 1),
    new_location_id   uuid REFERENCES ssh_key_locations (id),
    verified_at       timestamptz,
    reverified_at     timestamptz,                 -- the latest fresh login before a removal
    remove_op_id      uuid,
    remove_verified_at timestamptz,                -- the fresh login the latest removal send relied on (= reverified_at then)
    remove_sent_at    timestamptz,
    removed_at        timestamptz,
    remove_failed_at  timestamptz,                 -- stamped by the guard on the edge into remove_failed (G20)
    undo_op_id        uuid,
    undo_sent_at      timestamptz,
    backup            text NOT NULL DEFAULT '' CHECK (char_length(backup) <= 200),
    job_count         integer NOT NULL DEFAULT 0 CHECK (job_count BETWEEN 0 AND 1000),
    updated_at        timestamptz NOT NULL,
    UNIQUE (rotation_id, n),
    UNIQUE (rotation_id, old_location_id),
    CONSTRAINT rotation_locations_skipped_reason CHECK (state <> 'skipped' OR skip_reason <> ''),
    CONSTRAINT rotation_locations_removing_columns CHECK (state NOT IN ('removing', 'removed') OR (verified_at IS NOT NULL
        AND reverified_at IS NOT NULL AND remove_verified_at IS NOT NULL AND remove_sent_at IS NOT NULL AND remove_op_id IS NOT NULL)),
    -- The removal columns come together; the login it relied on is the re-check, not older than the original
    -- verification, not after the send, and at most 15 minutes before it.
    CONSTRAINT rotation_locations_remove_together CHECK ((remove_op_id IS NULL) = (remove_sent_at IS NULL)
        AND (remove_sent_at IS NULL) = (remove_verified_at IS NULL)),
    CONSTRAINT rotation_locations_removal_fresh CHECK (remove_sent_at IS NULL OR (verified_at IS NOT NULL AND reverified_at IS NOT NULL
        AND remove_verified_at >= verified_at AND remove_verified_at <= reverified_at AND remove_verified_at <= remove_sent_at
        AND remove_verified_at >= remove_sent_at - interval '15 minutes')),
    CONSTRAINT rotation_locations_removed_pair CHECK ((state = 'removed') = (removed_at IS NOT NULL)),
    -- added <= verified < re-checked (a later login), removal sent <= removed, add re-sent after the first send, undo
    -- after the latest add send
    CONSTRAINT rotation_locations_times CHECK ((add_sent_at IS NULL OR verified_at IS NULL OR verified_at >= add_sent_at)
        AND (verified_at IS NULL OR reverified_at IS NULL OR reverified_at > verified_at)
        AND (remove_sent_at IS NULL OR removed_at IS NULL OR removed_at >= remove_sent_at)
        AND (add_sent_at IS NULL OR undo_sent_at IS NULL OR undo_sent_at >= add_sent_at)
        AND (add_resent_at IS NULL OR (add_sent_at IS NOT NULL AND add_resent_at >= add_sent_at))
        AND (add_resent_at IS NULL OR undo_sent_at IS NULL OR undo_sent_at >= add_resent_at)),
    CONSTRAINT rotation_locations_add_resent CHECK ((add_resend_count = 0) = (add_resent_at IS NULL)),
    CONSTRAINT rotation_locations_undo_sent CHECK (state NOT IN ('undoing', 'undone') OR (undo_op_id IS NOT NULL AND undo_sent_at IS NOT NULL)),
    CONSTRAINT rotation_locations_remove_failed_at CHECK (state <> 'remove_failed' OR remove_failed_at IS NOT NULL),
    CONSTRAINT rotation_locations_verified_state CHECK (state <> 'verified' OR verified_at IS NOT NULL),
    CONSTRAINT rotation_locations_recheck_needs_verified CHECK (reverified_at IS NULL OR verified_at IS NOT NULL),
    CONSTRAINT rotation_locations_add_sent CHECK (state NOT IN ('adding', 'added') OR (add_op_id IS NOT NULL AND add_sent_at IS NOT NULL)),
    CONSTRAINT rotation_locations_undo_needs_add CHECK (state NOT IN ('undoing', 'undone', 'undo_failed') OR add_sent_at IS NOT NULL),
    CONSTRAINT rotation_locations_verified_needs_add CHECK (verified_at IS NULL OR add_sent_at IS NOT NULL)
);
CREATE INDEX rotation_locations_target ON rotation_locations (target_id);

-- Every operation id a location ever sent with (add, removal, undo), written by rotation_locations_guard when an op id
-- column takes a new value: an op id is used once, across locations, kinds and attempts (G23), so a job or agent layer
-- that deduplicates by op id never hands back an earlier attempt's result. Append-only (no UPDATE, no DELETE).
CREATE TABLE rotation_op_ids (
    op_id       uuid PRIMARY KEY,
    location_id uuid NOT NULL REFERENCES rotation_locations (id),
    kind        text NOT NULL CHECK (kind IN ('add', 'remove', 'undo'))
);

-- The run guard.
-- LOCK ORDER of every transaction that writes these tables (the stores of Tasks 8, 9, 11).
--   INSERTING a run: the policy row FOR UPDATE first (the run insert reads it FOR SHARE: a transaction that
--   inserts and then updates the policy without having locked it FOR UPDATE upgrades a share lock and deadlocks
--   with a second inserter; an uncommitted run insert also blocks every UPDATE of that policy from other
--   connections), then the run insert, then the targets, ssh_keys, location rows.
--   an EXISTING run: the run row FOR UPDATE first, then its policy row, then the targets (ascending id; the
--   CALLER orders them), then ssh_keys rows (managed_private_keys rows after the ssh_keys row of their key:
--   destruction and un-retire lock the two in that order), then the location rows (rotation_locations and
--   ssh_key_locations), then rotation_steps.
-- Never FOR SHARE on the run first and an update later (two such transactions deadlock on the upgrade). WHY
-- every writer of rotation_locations takes the run first, the sweep's job_count bump included: an UPDATE of a
-- location locks the location row before this trigger reads the run FOR SHARE, so a writer holding a location
-- and waiting for the run deadlocks (SQLSTATE 40P01) with one holding the run and updating the location.
-- Inserting a rotation_steps row takes FOR KEY SHARE on the run: insert steps after the run lock.
-- UNLOCKED READS: the guards read the sibling locations of a file, the platform credential, the run's keys, the
-- run's locations (rotations_guard: adding/planned/added rows and the end conditions), the old place at a location
-- insert and the new place when new_location_id is set, without a lock (the connection-key flag of the old and new
-- places and the new place's liveness at a send are read FOR SHARE: they conflict with a concurrent scan's update of
-- those rows). rotations_guard's reads of the run's locations are safe on their own (every location writer holds the
-- run FOR SHARE, which conflicts with the run UPDATE); everything else is safe only because every writer holds the run
-- FOR UPDATE, which serializes all writers of one run, AND runs at READ COMMITTED (db/tx.go): a writer that waited for
-- the run lock then reads the rows the previous holder committed. Under REPEATABLE READ or SERIALIZABLE it would read
-- its old snapshot; a writer that skips the run lock can race these reads.
-- The location guard also INSERTs into rotation_op_ids (its foreign key takes FOR KEY SHARE on the location row the
-- statement already holds): no new lock order.
-- NEVER wait on another connection (a second transaction of the service, a hook, a channel) while holding a lock
-- of this table family, including the ones the triggers take implicitly (run FOR SHARE on every location write,
-- policy FOR SHARE on a run insert, key and private-key FOR SHARE on destroy/un-retire, FOR KEY SHARE through
-- foreign keys, the audit advisory lock): PostgreSQL cannot see a cycle that passes through Go.
-- Rules: an insert is a preview (dry_run_notified, no key chosen yet) of a live policy's own live generated key
-- (the policy row is read FOR SHARE, so it cannot be deleted at the same moment); a finished run never changes;
-- the policy and the old key never change; the new key is set once, from NULL, to a generated key that
-- rotated_from the old one, is not Alice's own and is the new key of no other run; removal_allowed rises only on
-- the edge overlap -> removing_old, which also needs the run's verification (verified_at, the new key) already
-- recorded before the statement, and no licence pause; verified_at is set once; a status change is an edge of
-- C8; a run ends only when no location has a send in flight, a completed run has no location still to remove or
-- failed to remove and none whose new key may be left behind unverified (verify_failed, add_failed after a send), and
-- an aborted run has every location ended; verifying_new, removing_old and completed are not entered while a location
-- is adding; overlap is not entered while a location is planned, adding or added (G24). The connection key is NOT
-- checked here (only by the location gate, at removal).
-- +goose StatementBegin
CREATE FUNCTION rotations_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
DECLARE
    finished constant text[] := ARRAY['completed', 'aborted', 'needs_attention', 'cancelled'];
    platform_fp text;
    pol record;
    k record;
BEGIN
    SELECT c.public_info->>'fingerprint' INTO platform_fp FROM public.credentials c WHERE c.purpose = 'platform_ssh';
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'dry_run_notified' OR NEW.new_ssh_key_id IS NOT NULL OR NEW.removal_allowed OR NEW.paused_license
                OR NEW.awaiting_decision OR NEW.started_at IS NOT NULL OR NEW.verified_at IS NOT NULL OR NEW.overlap_until IS NOT NULL
                OR NEW.finished_at IS NOT NULL OR NEW.kept_count <> 0 OR NEW.result_code <> '' THEN
            RAISE EXCEPTION 'a rotation starts as a preview' USING ERRCODE = 'Z1013';
        END IF;
        SELECT p.ssh_key_id, p.deleted_at INTO pol FROM public.rotation_policies p WHERE p.id = NEW.policy_id FOR SHARE OF p;
        IF NOT FOUND OR pol.deleted_at IS NOT NULL OR pol.ssh_key_id <> NEW.old_ssh_key_id THEN
            RAISE EXCEPTION 'a rotation replaces the key of its live policy' USING ERRCODE = 'Z1013';
        END IF;
        SELECT s.managed, s.is_platform_key, s.retired_at, s.fingerprint_sha256 INTO k FROM public.ssh_keys s WHERE s.id = NEW.old_ssh_key_id;
        IF NOT FOUND OR NOT k.managed OR k.is_platform_key OR k.retired_at IS NOT NULL
                OR k.fingerprint_sha256 IS NOT DISTINCT FROM platform_fp THEN
            RAISE EXCEPTION 'only a live key Alice generated is rotated, never Alice''s own key' USING ERRCODE = 'Z1013';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = ANY (finished) THEN
        RAISE EXCEPTION 'a finished rotation cannot change' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.id <> OLD.id OR NEW.policy_id <> OLD.policy_id OR NEW.old_ssh_key_id <> OLD.old_ssh_key_id THEN
        RAISE EXCEPTION 'a rotation''s policy and old key are fixed' USING ERRCODE = 'Z1013';
    END IF;
    IF OLD.new_ssh_key_id IS NOT NULL AND NEW.new_ssh_key_id IS DISTINCT FROM OLD.new_ssh_key_id THEN
        RAISE EXCEPTION 'the new key of a rotation is chosen once' USING ERRCODE = 'Z1013';
    END IF;
    IF OLD.new_ssh_key_id IS NULL AND NEW.new_ssh_key_id IS NOT NULL THEN
        SELECT s.managed, s.is_platform_key, s.retired_at, s.fingerprint_sha256, s.rotated_from INTO k
          FROM public.ssh_keys s WHERE s.id = NEW.new_ssh_key_id;
        IF NOT FOUND OR NOT k.managed OR k.is_platform_key OR k.retired_at IS NOT NULL OR k.rotated_from IS DISTINCT FROM NEW.old_ssh_key_id
                OR k.fingerprint_sha256 IS NOT DISTINCT FROM platform_fp THEN
            RAISE EXCEPTION 'the new key is a generated key that replaces the old one, never Alice''s own key' USING ERRCODE = 'Z1013';
        END IF;
    END IF;
    IF OLD.verified_at IS NOT NULL AND NEW.verified_at IS DISTINCT FROM OLD.verified_at THEN
        RAISE EXCEPTION 'the verification time of a rotation is set once' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.removal_allowed IS DISTINCT FROM OLD.removal_allowed
            AND NOT (NEW.removal_allowed AND OLD.status = 'overlap' AND NEW.status = 'removing_old') THEN
        RAISE EXCEPTION 'removal is allowed only on entering removing_old from the overlap' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.status IN ('verifying_new', 'removing_old', 'completed') AND NEW.status <> OLD.status
            AND EXISTS (SELECT 1 FROM public.rotation_locations l WHERE l.rotation_id = NEW.id AND l.state = 'adding') THEN
        RAISE EXCEPTION 'a rotation does not move on while an add is still in flight' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.status = 'overlap' AND OLD.status <> 'overlap'
            AND EXISTS (SELECT 1 FROM public.rotation_locations l WHERE l.rotation_id = NEW.id AND l.state IN ('planned', 'adding', 'added')) THEN
        -- G24: in the overlap these rows have no edge but an undo, so the run could only roll back.
        RAISE EXCEPTION 'the overlap starts when no location is still to add or to verify' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.status = 'removing_old' AND OLD.status = 'overlap' AND (OLD.verified_at IS NULL OR OLD.new_ssh_key_id IS NULL
            OR NEW.paused_license) THEN
        RAISE EXCEPTION 'removal starts on a verification the run already had, and not while paused for the licence' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.status <> OLD.status AND NOT (CASE OLD.status
            WHEN 'dry_run_notified' THEN NEW.status IN ('adding_new', 'cancelled')
            WHEN 'adding_new' THEN NEW.status IN ('overlap', 'verifying_new', 'rolling_back')
            WHEN 'verifying_new' THEN NEW.status IN ('overlap', 'rolling_back')
            WHEN 'overlap' THEN NEW.status IN ('removing_old', 'rolling_back')
            WHEN 'removing_old' THEN NEW.status IN ('completed', 'needs_attention')
            WHEN 'rolling_back' THEN NEW.status IN ('aborted', 'needs_attention')
            ELSE false END) THEN
        RAISE EXCEPTION 'this status change is not an edge of the rotation' USING ERRCODE = 'Z1013';
    END IF;
    IF NEW.status = ANY (finished) AND NEW.status <> OLD.status THEN
        IF EXISTS (SELECT 1 FROM public.rotation_locations l WHERE l.rotation_id = NEW.id AND l.state IN ('adding', 'removing', 'undoing'))
                OR (NEW.status = 'completed' AND EXISTS (SELECT 1 FROM public.rotation_locations l
                    WHERE l.rotation_id = NEW.id AND (l.state IN ('planned', 'added', 'verified', 'remove_failed', 'verify_failed')
                      OR (l.state = 'add_failed' AND l.add_sent_at IS NOT NULL))))
                OR (NEW.status = 'aborted' AND EXISTS (SELECT 1 FROM public.rotation_locations l
                    WHERE l.rotation_id = NEW.id AND l.state NOT IN ('skipped', 'cancelled', 'undone', 'undo_failed')
                      AND NOT (l.state = 'add_failed' AND l.add_sent_at IS NULL))) THEN
            RAISE EXCEPTION 'a rotation ends when none of its locations is still to change (completed: none failed to remove or left an unverified new key; aborted: every one ended)' USING ERRCODE = 'Z1013';
        END IF;
    END IF;
    RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER rotations_guard BEFORE INSERT OR UPDATE ON rotations
    FOR EACH ROW EXECUTE FUNCTION rotations_guard();

-- The location guard (the old-key rule and the C8 location table; SQLSTATE Z1011). The run is read FOR SHARE
-- (take the run FOR UPDATE first: see the lock order above): a concurrent change of the run (finishing it,
-- leaving removing_old) waits for this row's transaction and the other way round, so no location changes under a
-- run that has just left the state the change needed.
-- Rules: a row is inserted only into a previewed run, as planned, skipped or cancelled, with no add, verify,
-- removal or undo column set, for a location of the run's old key (same target, user and path). A status change
-- is an edge of the location table (below) AND respects the run's status: an add is started (and re-sent: the
-- re-send counter rises by one with add_resent_at, G25) only while the run is adding_new and not paused for the
-- licence; an add finishes (added, add_failed) only in adding_new; a verification result (verified, unverifiable,
-- verify_failed from adding/added) only in adding_new or verifying_new; removing, removed and remove_failed only in
-- removing_old; undoing, undone and undo_failed (and a re-sent undo) only in rolling_back. skipped, cancelled,
-- removed, undone and undo_failed never change again; remove_failed changes only by a retry through the full gate,
-- which needs a re-check strictly later than the earlier one, than the failed send and than the failure time this
-- trigger stamps (remove_failed_at, G20), a later send time and a new op id. verified_at is set once, on the edge into
-- verified; add_sent_at on entering adding only; the undo columns only while undoing, required there and on undone,
-- never cleared; an undo_failed row carries a reason (G21). reverified_at never goes back and is never cleared, and
-- changes only on a verified row or in a statement whose new state is removing (G20). Every op id is new for good
-- (rotation_op_ids, G23).
-- The removal columns change only while the row is removing and every row that is or becomes removing (or
-- removed) passes the old-key gate: the run is removing_old with removal_allowed; neither key is Alice's own
-- (platform fingerprint, is_platform_key, the connection key's locations); the verification (verified_at,
-- add_sent_at) is the one the row already had; the re-check (reverified_at, strictly later than the
-- verification) is the login the send relied on (remove_verified_at = reverified_at, at most 15 minutes before
-- remove_sent_at); a re-send keeps remove_op_id and does not go back in time. A SEND (the first, a retry from
-- remove_failed, a re-send) also needs: the run not paused for the licence, every other location of the run in the
-- same target and file verified, removed, or removing with its own re-check at most 15 minutes before this send
-- (G22; skipped, kept and failed ones block), and the new key's place recorded (new_location_id) and still live
-- (neither removed by Alice nor missing). Finishing (removing -> removed) and counter updates of a removing row
-- re-check the run, the keys and the connection-key flags but are not sends.
-- +goose StatementBegin
CREATE FUNCTION rotation_locations_guard() RETURNS trigger LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
DECLARE
    finished constant text[] := ARRAY['completed', 'aborted', 'needs_attention', 'cancelled'];
    run record;
    loc record;
    old_key record;
    new_key record;
    platform_fp text;
    sending_add boolean;
    sending_undo boolean;
    sending_removal boolean;
    conn_key boolean;
    conn_flag boolean;
BEGIN
    SELECT r.status, r.removal_allowed, r.old_ssh_key_id, r.new_ssh_key_id, r.paused_license INTO run
      FROM public.rotations r WHERE r.id = NEW.rotation_id FOR SHARE OF r;
    IF NOT FOUND OR run.status = ANY (finished) THEN
        RAISE EXCEPTION 'a finished rotation''s locations cannot change' USING ERRCODE = 'Z1011';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF run.status <> 'dry_run_notified' OR NEW.state NOT IN ('planned', 'skipped', 'cancelled')
                OR NEW.add_op_id IS NOT NULL OR NEW.add_sent_at IS NOT NULL OR NEW.added_line_no IS NOT NULL
                OR NEW.new_location_id IS NOT NULL OR NEW.verified_at IS NOT NULL OR NEW.reverified_at IS NOT NULL
                OR NEW.remove_op_id IS NOT NULL OR NEW.remove_verified_at IS NOT NULL OR NEW.remove_sent_at IS NOT NULL
                OR NEW.removed_at IS NOT NULL OR NEW.undo_op_id IS NOT NULL OR NEW.undo_sent_at IS NOT NULL
                OR NEW.add_resend_count <> 0 OR NEW.add_resent_at IS NOT NULL OR NEW.remove_failed_at IS NOT NULL THEN
            RAISE EXCEPTION 'a location starts planned, skipped or cancelled in a previewed rotation' USING ERRCODE = 'Z1011';
        END IF;
        SELECT l.ssh_key_id, l.target_id, l.os_user, l.file_path INTO loc FROM public.ssh_key_locations l WHERE l.id = NEW.old_location_id;
        IF NOT FOUND OR loc.ssh_key_id <> run.old_ssh_key_id OR loc.target_id <> NEW.target_id OR loc.os_user <> NEW.os_user
                OR loc.file_path <> NEW.file_path THEN
            RAISE EXCEPTION 'a location is a place of the old key' USING ERRCODE = 'Z1011';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id <> OLD.id OR NEW.rotation_id <> OLD.rotation_id OR NEW.n <> OLD.n OR NEW.old_location_id <> OLD.old_location_id
            OR NEW.target_id <> OLD.target_id OR NEW.os_user <> OLD.os_user OR NEW.file_path <> OLD.file_path THEN
        RAISE EXCEPTION 'the identity of a rotation location cannot change' USING ERRCODE = 'Z1011';
    END IF;
    IF OLD.state IN ('skipped', 'cancelled', 'removed', 'undone', 'undo_failed')
            OR (OLD.state = 'remove_failed' AND NEW.state <> 'removing') THEN
        RAISE EXCEPTION 'a location that ended does not change' USING ERRCODE = 'Z1011';
    END IF;
    IF OLD.verified_at IS NOT NULL AND NEW.verified_at IS DISTINCT FROM OLD.verified_at THEN
        RAISE EXCEPTION 'the verification time of a location is set once' USING ERRCODE = 'Z1011';
    END IF;
    -- Each column is written only in the statement that takes its own step (ruling G16): the add time and the
    -- add op id on entering adding (the op id may be replaced only by a re-send, neither is ever cleared; the time
    -- never changes again), the verification time on the edge into verified, the undo columns when the row is
    -- undoing.
    IF NEW.add_sent_at IS DISTINCT FROM OLD.add_sent_at AND NOT (OLD.add_sent_at IS NULL AND OLD.state = 'planned' AND NEW.state = 'adding') THEN
        RAISE EXCEPTION 'the add time is set when the add starts and never changes' USING ERRCODE = 'Z1011';
    END IF;
    -- G25: an add RE-SEND is one statement on an adding row that raises add_resend_count by exactly one and sets
    -- add_resent_at, never earlier than the latest send (a backward clock step fails closed, G14); a same-instant
    -- re-send (a frozen clock) still counts. Neither is ever cleared. It is gated as a send below.
    IF NEW.add_resend_count IS DISTINCT FROM OLD.add_resend_count OR NEW.add_resent_at IS DISTINCT FROM OLD.add_resent_at THEN
        IF NOT (OLD.state = 'adding' AND NEW.state = 'adding' AND NEW.add_resend_count = OLD.add_resend_count + 1
                AND NEW.add_resent_at IS NOT NULL AND (OLD.add_resent_at IS NULL OR NEW.add_resent_at >= OLD.add_resent_at)) THEN
            RAISE EXCEPTION 'an add is re-sent from an adding row, one re-send at a time, never back in time' USING ERRCODE = 'Z1011';
        END IF;
    END IF;
    IF NEW.add_op_id IS DISTINCT FROM OLD.add_op_id AND NOT (NEW.add_op_id IS NOT NULL AND NEW.state = 'adding'
            AND (OLD.state = 'planned' OR (OLD.state = 'adding' AND NEW.add_resend_count = OLD.add_resend_count + 1))) THEN
        RAISE EXCEPTION 'the add operation id is set when the add starts or is re-sent and is never cleared' USING ERRCODE = 'Z1011';
    END IF;
    IF NEW.verified_at IS DISTINCT FROM OLD.verified_at AND NOT (NEW.state = 'verified' AND OLD.state IN ('adding', 'added')) THEN
        RAISE EXCEPTION 'the verification time is set with the edge into verified' USING ERRCODE = 'Z1011';
    END IF;
    IF (NEW.undo_op_id IS DISTINCT FROM OLD.undo_op_id OR NEW.undo_sent_at IS DISTINCT FROM OLD.undo_sent_at) AND NEW.state <> 'undoing' THEN
        RAISE EXCEPTION 'the undo columns are written only while the location is undoing' USING ERRCODE = 'Z1011';
    END IF;
    -- G21: once set, the undo columns are never cleared (CHECK rotation_locations_undo_sent requires them on undoing
    -- and undone).
    IF (OLD.undo_op_id IS NOT NULL AND NEW.undo_op_id IS NULL) OR (OLD.undo_sent_at IS NOT NULL AND NEW.undo_sent_at IS NULL) THEN
        RAISE EXCEPTION 'the undo columns are never cleared' USING ERRCODE = 'Z1011';
    END IF;
    -- G20: the re-check never goes back and is never cleared; it changes only on a verified row (a recorded re-check)
    -- or in a statement whose new state is removing (a send, a retry, a re-check of a removing row). Every other edge
    -- (into remove_failed, kept_old, the undo states, removed) keeps it, so a failure statement cannot erase the
    -- evidence a retry is compared with.
    IF NEW.reverified_at IS DISTINCT FROM OLD.reverified_at THEN
        IF NEW.reverified_at IS NULL OR (OLD.reverified_at IS NOT NULL AND NEW.reverified_at < OLD.reverified_at) THEN
            RAISE EXCEPTION 'a re-check never goes back and is never cleared' USING ERRCODE = 'Z1011';
        END IF;
        IF NOT (NEW.state = 'removing' OR (OLD.state = 'verified' AND NEW.state = 'verified')) THEN
            RAISE EXCEPTION 'a re-check is recorded on a verified row or with a removal' USING ERRCODE = 'Z1011';
        END IF;
    END IF;
    -- G20: the failure time of a removal is stamped by this trigger only (below).
    IF NEW.remove_failed_at IS DISTINCT FROM OLD.remove_failed_at THEN
        RAISE EXCEPTION 'the failure time of a removal is recorded by the database' USING ERRCODE = 'Z1011';
    END IF;
    IF NEW.state <> OLD.state AND NOT (CASE OLD.state
            WHEN 'planned' THEN NEW.state IN ('adding', 'cancelled', 'add_failed')
            WHEN 'adding' THEN NEW.state IN ('added', 'add_failed', 'verified', 'unverifiable', 'verify_failed', 'undoing')
            WHEN 'added' THEN NEW.state IN ('add_failed', 'verified', 'unverifiable', 'verify_failed', 'undoing', 'undo_failed')
            WHEN 'verified' THEN NEW.state IN ('removing', 'remove_failed', 'kept_old', 'undoing', 'undo_failed')
            WHEN 'unverifiable' THEN NEW.state IN ('kept_old', 'undoing', 'undo_failed')
            WHEN 'verify_failed' THEN NEW.state IN ('undoing', 'undo_failed')
            WHEN 'add_failed' THEN NEW.state IN ('undoing', 'undo_failed')
            WHEN 'kept_old' THEN NEW.state IN ('undoing', 'undo_failed')
            WHEN 'removing' THEN NEW.state IN ('removed', 'remove_failed')
            WHEN 'remove_failed' THEN NEW.state = 'removing'
            WHEN 'undoing' THEN NEW.state IN ('undone', 'undo_failed')
            ELSE false END) THEN
        RAISE EXCEPTION 'this state change is not an edge of the location table' USING ERRCODE = 'Z1011';
    END IF;
    -- A pending undo that ends without a send (retries exhausted, the old key already gone) carries a reason
    -- and no undo timestamps.
    IF NEW.state = 'undo_failed' AND OLD.state <> 'undoing' AND (NEW.error_code = ''
            OR NEW.undo_op_id IS DISTINCT FROM OLD.undo_op_id OR NEW.undo_sent_at IS DISTINCT FROM OLD.undo_sent_at) THEN
        RAISE EXCEPTION 'an undo that sent nothing ends with a reason and no undo time' USING ERRCODE = 'Z1011';
    END IF;
    -- G21: a sent undo that failed says why too.
    IF NEW.state = 'undo_failed' AND OLD.state = 'undoing' AND NEW.error_code = '' THEN
        RAISE EXCEPTION 'a failed undo ends with a reason' USING ERRCODE = 'Z1011';
    END IF;

    -- The run's status gates the edges. An ADD send is the move planned -> adding or a re-send (G25).
    sending_add := NEW.state = 'adding' AND (OLD.state <> 'adding' OR NEW.add_resend_count <> OLD.add_resend_count
                                               OR NEW.add_op_id IS DISTINCT FROM OLD.add_op_id);
    sending_undo := NEW.state = 'undoing' AND (OLD.state <> 'undoing' OR NEW.undo_sent_at IS DISTINCT FROM OLD.undo_sent_at
                                                 OR NEW.undo_op_id IS DISTINCT FROM OLD.undo_op_id);
    IF (sending_add OR (NEW.state <> OLD.state AND NEW.state IN ('added', 'add_failed'))) AND run.status <> 'adding_new' THEN
        RAISE EXCEPTION 'an add is made only while the rotation is adding the new key' USING ERRCODE = 'Z1011';
    END IF;
    IF sending_add AND run.paused_license THEN
        RAISE EXCEPTION 'no add is sent while the rotation is paused for the licence' USING ERRCODE = 'Z1011';
    END IF;
    IF NEW.state <> OLD.state AND NEW.state IN ('verified', 'unverifiable', 'verify_failed') AND OLD.state IN ('adding', 'added')
            AND run.status NOT IN ('adding_new', 'verifying_new') THEN
        RAISE EXCEPTION 'a verification is recorded only while the rotation verifies the new key' USING ERRCODE = 'Z1011';
    END IF;
    IF NEW.state <> OLD.state AND NEW.state IN ('remove_failed') AND run.status <> 'removing_old' THEN
        RAISE EXCEPTION 'a removal ends only while the rotation is removing the old key' USING ERRCODE = 'Z1011';
    END IF;
    IF (sending_undo OR (NEW.state <> OLD.state AND NEW.state IN ('undone', 'undo_failed'))) AND run.status <> 'rolling_back' THEN
        RAISE EXCEPTION 'an undo is made only while the rotation is rolling back' USING ERRCODE = 'Z1011';
    END IF;

    -- A new location belongs to the run's new key and is the same place.
    IF NEW.new_location_id IS DISTINCT FROM OLD.new_location_id THEN
        IF OLD.new_location_id IS NOT NULL OR run.new_ssh_key_id IS NULL THEN
            RAISE EXCEPTION 'the new location is recorded once, for the new key' USING ERRCODE = 'Z1011';
        END IF;
        SELECT l.ssh_key_id, l.target_id, l.os_user, l.file_path INTO loc FROM public.ssh_key_locations l WHERE l.id = NEW.new_location_id;
        IF NOT FOUND OR loc.ssh_key_id <> run.new_ssh_key_id OR loc.target_id <> NEW.target_id OR loc.os_user <> NEW.os_user
                OR loc.file_path <> NEW.file_path THEN
            RAISE EXCEPTION 'the new location is a place of the new key' USING ERRCODE = 'Z1011';
        END IF;
    END IF;

    -- The removal columns move only with a removal that is sent.
    IF NEW.remove_op_id IS DISTINCT FROM OLD.remove_op_id OR NEW.remove_verified_at IS DISTINCT FROM OLD.remove_verified_at
            OR NEW.remove_sent_at IS DISTINCT FROM OLD.remove_sent_at THEN
        IF NEW.state <> 'removing' THEN
            RAISE EXCEPTION 'the removal columns change only while the location is removing' USING ERRCODE = 'Z1011';
        END IF;
    END IF;

    IF NEW.state IN ('removing', 'removed') THEN
        -- The old-key gate.
        IF run.status <> 'removing_old' OR NOT run.removal_allowed THEN
            RAISE EXCEPTION 'the old key may be removed only while its rotation is removing it' USING ERRCODE = 'Z1011';
        END IF;
        SELECT c.public_info->>'fingerprint' INTO platform_fp FROM public.credentials c WHERE c.purpose = 'platform_ssh';
        SELECT s.fingerprint_sha256 AS fp, s.is_platform_key AS plat INTO old_key FROM public.ssh_keys s WHERE s.id = run.old_ssh_key_id;
        SELECT s.fingerprint_sha256 AS fp, s.is_platform_key AS plat INTO new_key FROM public.ssh_keys s WHERE s.id = run.new_ssh_key_id;
        -- The connection-key flag is read with the rows locked FOR SHARE and WITHOUT the flag in the WHERE clause: a row
        -- that does not match yet would not be waited for, and a flag being set by a concurrent scan would be missed.
        conn_key := false;
        FOR conn_flag IN SELECT l.is_alice_connection_key FROM public.ssh_key_locations l
                         WHERE l.id IN (NEW.old_location_id, NEW.new_location_id) FOR SHARE OF l LOOP
            conn_key := conn_key OR conn_flag;
        END LOOP;
        IF old_key.fp IS NULL OR new_key.fp IS NULL OR old_key.plat OR new_key.plat
                OR old_key.fp IS NOT DISTINCT FROM platform_fp OR new_key.fp IS NOT DISTINCT FROM platform_fp OR conn_key THEN
            RAISE EXCEPTION 'Alice''s own key is never removed, nor replaced by a key of Alice''s own' USING ERRCODE = 'Z1011';
        END IF;
        -- The verification is the one the row already had; the login is read from NEW only for the re-check.
        IF OLD.verified_at IS NULL OR NEW.verified_at IS DISTINCT FROM OLD.verified_at OR NEW.add_sent_at IS DISTINCT FROM OLD.add_sent_at THEN
            RAISE EXCEPTION 'a removal relies on a verification the location already had' USING ERRCODE = 'Z1011';
        END IF;
        IF NEW.state = 'removed' THEN
            -- Finishing: the send columns stay as they were.
            IF NEW.remove_op_id IS DISTINCT FROM OLD.remove_op_id OR NEW.remove_verified_at IS DISTINCT FROM OLD.remove_verified_at
                    OR NEW.remove_sent_at IS DISTINCT FROM OLD.remove_sent_at OR NEW.removed_at IS NULL THEN
                RAISE EXCEPTION 'a finished removal keeps the send it relied on' USING ERRCODE = 'Z1011';
            END IF;
        ELSE
            IF NEW.reverified_at IS NULL OR (OLD.reverified_at IS NOT NULL AND NEW.reverified_at < OLD.reverified_at) THEN
                RAISE EXCEPTION 'a removal needs a re-check that does not go back in time' USING ERRCODE = 'Z1011';
            END IF;
            sending_removal := OLD.state <> 'removing' OR NEW.remove_sent_at IS DISTINCT FROM OLD.remove_sent_at;
            IF sending_removal THEN
                -- A send (the first, a retry from remove_failed, or a re-send): the login it relied on is the re-check.
                -- A re-send keeps the op id and does not go back in time; a retry after a failed send does not either.
                IF NEW.remove_sent_at IS NULL OR NEW.remove_op_id IS NULL OR NEW.remove_verified_at IS DISTINCT FROM NEW.reverified_at
                        OR (OLD.state = 'removing' AND NEW.remove_op_id IS DISTINCT FROM OLD.remove_op_id)
                        OR (OLD.remove_sent_at IS NOT NULL AND NEW.remove_sent_at < OLD.remove_sent_at)
                        OR (OLD.state = 'verified' AND OLD.remove_sent_at IS NOT NULL) THEN
                    RAISE EXCEPTION 'a removal is sent on the re-check it relied on' USING ERRCODE = 'Z1011';
                END IF;
                IF OLD.state = 'remove_failed' AND (NEW.remove_op_id IS NOT DISTINCT FROM OLD.remove_op_id
                        OR (OLD.reverified_at IS NOT NULL AND NEW.reverified_at <= OLD.reverified_at)
                        OR OLD.remove_failed_at IS NULL OR NEW.reverified_at <= OLD.remove_failed_at
                        OR (OLD.remove_sent_at IS NOT NULL AND (NEW.remove_sent_at <= OLD.remove_sent_at OR NEW.reverified_at <= OLD.remove_sent_at))) THEN
                    -- G3', G20: a retry relies on a login strictly newer than the one used before, than the failed send
                    -- and than the failure (remove_failed_at, stamped below), a newer send time and a new operation id;
                    -- the stored values never satisfy the gate again.
                    RAISE EXCEPTION 'a retried removal needs a new re-check, a new send time and a new operation id' USING ERRCODE = 'Z1011';
                END IF;
                IF run.paused_license THEN
                    RAISE EXCEPTION 'no removal is sent while the rotation is paused for the licence' USING ERRCODE = 'Z1011';
                END IF;
                -- G18, G22: every other location of the run in the file is verified, removed, or removing on a re-check
                -- of its own at most 15 minutes before THIS send (this send removes that user's old line too).
                IF EXISTS (SELECT 1 FROM public.rotation_locations o WHERE o.rotation_id = NEW.rotation_id AND o.target_id = NEW.target_id
                           AND o.file_path = NEW.file_path AND o.id <> NEW.id AND (o.state NOT IN ('verified', 'removing', 'removed')
                               OR (o.state = 'removing' AND (o.reverified_at IS NULL
                                   OR o.reverified_at < NEW.remove_sent_at - interval '15 minutes')))) THEN
                    RAISE EXCEPTION 'a file is changed only when every other location of the rotation in it is verified, removed or freshly re-checked (skipped and kept ones block it)' USING ERRCODE = 'Z1011';
                END IF;
                IF NEW.new_location_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.ssh_key_locations l WHERE l.id = NEW.new_location_id
                           AND l.removed_by_alice_at IS NULL AND l.missing_since IS NULL FOR SHARE OF l) THEN
                    RAISE EXCEPTION 'the new key must be recorded and live in the file before the old key leaves it' USING ERRCODE = 'Z1011';
                END IF;
            ELSIF NEW.remove_op_id IS DISTINCT FROM OLD.remove_op_id OR NEW.remove_verified_at IS DISTINCT FROM OLD.remove_verified_at THEN
                RAISE EXCEPTION 'a removal''s send columns change together' USING ERRCODE = 'Z1011';
            END IF;
        END IF;
    END IF;

    -- G20: the failure time of a removal. updated_at is the application's (it writes it on every statement and may
    -- write any value), so the stamp is the latest of the row's own supplied times: this statement's updated_at and
    -- every time the row already recorded. The database never reads now() (the application clock is injected).
    IF NEW.state = 'remove_failed' AND OLD.state <> 'remove_failed' THEN
        NEW.remove_failed_at := GREATEST(NEW.updated_at, OLD.updated_at, OLD.remove_failed_at, OLD.add_sent_at, OLD.add_resent_at,
                                         OLD.verified_at, OLD.reverified_at, OLD.remove_verified_at, OLD.remove_sent_at);
    END IF;
    -- G23: an operation id is used once, for good (rotation_op_ids' primary key, 23505). Last, so a refusal above
    -- answers Z1011 first.
    IF NEW.add_op_id IS NOT NULL AND NEW.add_op_id IS DISTINCT FROM OLD.add_op_id THEN
        INSERT INTO public.rotation_op_ids (op_id, location_id, kind) VALUES (NEW.add_op_id, NEW.id, 'add');
    END IF;
    IF NEW.remove_op_id IS NOT NULL AND NEW.remove_op_id IS DISTINCT FROM OLD.remove_op_id THEN
        INSERT INTO public.rotation_op_ids (op_id, location_id, kind) VALUES (NEW.remove_op_id, NEW.id, 'remove');
    END IF;
    IF NEW.undo_op_id IS NOT NULL AND NEW.undo_op_id IS DISTINCT FROM OLD.undo_op_id THEN
        INSERT INTO public.rotation_op_ids (op_id, location_id, kind) VALUES (NEW.undo_op_id, NEW.id, 'undo');
    END IF;
    RETURN NEW;
END $$;
-- +goose StatementEnd
CREATE TRIGGER rotation_locations_guard BEFORE INSERT OR UPDATE ON rotation_locations
    FOR EACH ROW EXECUTE FUNCTION rotation_locations_guard();

-- The recorded steps of a run (§7.4 rotation_steps, §26.8 "recorded steps"), append-only.
CREATE TABLE rotation_steps (
    id          uuid PRIMARY KEY,
    rotation_id uuid NOT NULL REFERENCES rotations (id),
    n           integer NOT NULL CHECK (n >= 1),
    location_id uuid REFERENCES rotation_locations (id),
    name        text NOT NULL CHECK (name ~ '^[a-z][a-z0-9_]{0,63}$'),
    status      text NOT NULL CHECK (status IN ('started', 'ok', 'failed', 'skipped')),
    at          timestamptz NOT NULL,
    params      jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(params) = 'object' AND octet_length(params::text) <= 4096),
    UNIQUE (rotation_id, n)
);

GRANT UPDATE (download_count, last_downloaded_at, destroyed_at, ciphertext, nonce, wrapped_dek, key_version)
    ON managed_private_keys TO alice_app;
GRANT UPDATE (retired_at) ON ssh_keys TO alice_app;
GRANT SELECT, INSERT ON rotation_policies, rotations, rotation_locations, rotation_steps, rotation_op_ids TO alice_app;
GRANT UPDATE (ssh_key_id, name, enabled, interval_days, overlap_minutes, notify_before_hours, new_key_type, next_run_at,
    preview_mailed_at, version, updated_at, deleted_at) ON rotation_policies TO alice_app;
GRANT UPDATE (new_ssh_key_id, status, paused_license, paused_at, awaiting_decision, decision_due_at, started_at, verified_at,
    overlap_until, reminder_sent_at, removal_allowed, kept_count, continued_by, continued_at, renotified_at, finished_at, result_code,
    updated_at, version) ON rotations TO alice_app;
GRANT UPDATE (state, skip_reason, error_code, add_op_id, add_sent_at, add_resend_count, add_resent_at, added_line_no, new_location_id,
    verified_at, reverified_at, remove_op_id, remove_verified_at, remove_sent_at, removed_at, undo_op_id, undo_sent_at, backup, job_count,
    updated_at, verify_note) ON rotation_locations TO alice_app;   -- not remove_failed_at: the guard stamps it

-- The delivered-notice lookup of a run (sshkeys noticeDelivered: the run's rotation.preview mails that were sent).
CREATE INDEX notifications_outbox_rotation_preview ON notifications_outbox ((params->>'rotation_id'))
    WHERE template_key = 'rotation.preview';

-- +goose Down
-- Correct only on a database without Phase 6 data, as 00006's and 00008's. The Down refuses, with a clear
-- message and SQLSTATE Z1012, when a generated key or its private key, an Ed25519 key, a destroyed key, a
-- rotation policy, a rotation run or a step exists; nothing is changed then (goose runs the Down in one
-- transaction). Discovered keys, certificate keys and everything of Phases 1-5 go through untouched.
-- +goose StatementBegin
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM managed_private_keys WHERE owner_type = 'ssh_key' OR algorithm = 'ed25519' OR destroyed_at IS NOT NULL)
            OR EXISTS (SELECT 1 FROM ssh_keys WHERE managed OR private_key_id IS NOT NULL OR rotated_from IS NOT NULL)
            OR EXISTS (SELECT 1 FROM rotation_policies) OR EXISTS (SELECT 1 FROM rotations) THEN
        RAISE EXCEPTION 'cannot migrate down: SSH key rotation data exists (generated keys, policies or runs); remove it first or restore a backup taken before 00010' USING ERRCODE = 'Z1012';
    END IF;
END $$;
-- +goose StatementEnd
